diff --git a/test/anthropic-migration.test.cjs b/test/anthropic-migration.test.cjs
new file mode 100644
index 0000000000000000000000000000000000000000..4a8ecd8333a6febd698115adc8d47d76716a32fc
--- /dev/null
+++ b/test/anthropic-migration.test.cjs
@@ -0,0 +1,68 @@
+const assert = require('node:assert/strict');
+const { readFileSync } = require('node:fs');
+const path = require('node:path');
+const vm = require('node:vm');
+const { test } = require('node:test');
+
+// Load route modules with isolated dependencies: no database, credentials,
+// network access, or application startup is needed to exercise their helpers.
+function loadHelper(file, helper, create) {
+    const router = {};
+    for (const method of ['use', 'get', 'post', 'patch', 'delete']) {
+        router[method] = () => router;
+    }
+    class MockAnthropic {
+        constructor() {
+            this.messages = { create };
+        }
+    }
+    const context = {
+        module: { exports: {} },
+        process: { env: {} },
+        console: { error() {} },
+        require(name) {
+            if (name === 'express') return { Router: () => router };
+            if (name === '@anthropic-ai/sdk') return MockAnthropic;
+            if (name === '../middleware/auth') return { verifyToken() {} };
+            if (name === '../middleware/roles') return { requireRole: () => () => {} };
+            return {};
+        }
+    };
+    const filename = path.join(__dirname, '..', file);
+    const source = readFileSync(filename, 'utf8');
+    vm.runInNewContext(`${source}\nmodule.exports = ${helper};`, context, { filename });
+    return context.module.exports;
+}
+
+const cases = [
+    ['routes/sessions.js', 'claudeAsk', 4096, 0.35],
+    ['routes/ai.js', 'askAI', 2048, 0.7],
+    ['routes/peer.js', 'askAI', 4096, 0.6]
+];
+
+for (const [file, helper, maxTokens, temperature] of cases) {
+    test(`${file}: replacement model preserves request and JSON text handling`, async () => {
+        let request;
+        const text = '{"ok":true}';
+        const ask = loadHelper(file, helper, async (params) => {
+            request = params;
+            return { content: [{ type: 'text', text }] };
+        });
+        const result = await ask('Return ONLY valid JSON.', 'Return an object with ok set to true.');
+        assert.equal(result, text);
+        assert.deepEqual(JSON.parse(result), { ok: true });
+        assert.deepEqual(JSON.parse(JSON.stringify(request)), {
+            model: 'claude-sonnet-5-5',
+            max_tokens: maxTokens,
+            system: 'Return ONLY valid JSON.',
+            messages: [{ role: 'user', content: 'Return an object with ok set to true.' }],
+            temperature
+        });
+    });
+
+    test(`${file}: provider errors reach existing route error handlers`, async () => {
+        const failure = new Error('Provider unavailable');
+        const ask = loadHelper(file, helper, async () => { throw failure; });
+        await assert.rejects(ask('system', 'user'), (error) => error === failure);
+    });
+}

